    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const appIcons = document.querySelectorAll('.app-icon');
            const backButtons = document.querySelectorAll('.back-btn');
            appIcons.forEach(icon => {
                icon.addEventListener('click', () => {
                    const pageId = icon.getAttribute('data-page-id');
                    const page = document.getElementById(pageId);
                    if (page) page.classList.add('active');
                });
            });
            backButtons.forEach(btn => {
                btn.addEventListener('click', () => {
                    const pageId = btn.getAttribute('data-page-id');
                    const page = document.getElementById(pageId);
                    if (page) page.classList.remove('active');
                });
            });

            const parser = new DOMParser();
            const parseXmlString = (xmlString) => {
                try {
                    return parser.parseFromString(`<root>${xmlString.trim()}</root>`, 'text/xml').documentElement.children;
                } catch (e) {
                    console.error("XML Parsing Error:", e, "String:", xmlString);
                    return [];
                }
            };

            const parseAndRenderList = (xmlString, containerId, alertGenerator, subtitleKey) => {
                const container = document.getElementById(containerId);
                if (!container) return;
                const items = parseXmlString(xmlString);
                for (const item of items) {
                    const listItem = document.createElement('div');
                    listItem.className = 'list-item list-item-arrow';
                    const content = document.createElement('div');
                    content.className = 'list-item-content';
                    const title = document.createElement('div');
                    title.className = 'list-item-title';
                    title.textContent = item.getAttribute('name');
                    content.appendChild(title);

                    const subtitleValue = item.getAttribute(subtitleKey);
                    if (subtitleValue) {
                        const subtitle = document.createElement('div');
                        subtitle.className = 'list-item-subtitle';
                        subtitle.textContent = `${subtitleKey.charAt(0).toUpperCase() + subtitleKey.slice(1)}: ${subtitleValue}`;
                        content.appendChild(subtitle);
                    }

                    listItem.appendChild(content);
                    listItem.onclick = () => alert(alertGenerator(item));
                    container.appendChild(listItem);
                }
            };

            parseAndRenderList(`$9`, 'skills-list-container', item => `【${item.getAttribute('name')}】\n效果：${item.getAttribute('effect')}\n熟练度：${item.getAttribute('level')}`, 'level');
            parseAndRenderList(`$10`, 'inventory-list-container', item => `【${item.getAttribute('name')}】\n数量：${item.getAttribute('quantity')}\n简介：${item.getAttribute('desc')}\n来历：${item.getAttribute('origin')}`, 'quantity');
            parseAndRenderList(`$11`, 'relations-list-container', item => `【${item.getAttribute('name')}】\n姓名：${item.getAttribute('name')}\n年龄：${item.getAttribute('age')}\n性格：${item.getAttribute('personality')}\n外貌：${item.getAttribute('appearance')}\n关系：${item.getAttribute('relation')}\n好感度：${item.getAttribute('affinity')}\n状态：${item.getAttribute('status')}\n内心想法：${item.getAttribute('thought')}`, 'relation');
            parseAndRenderList(`$12`, 'tasks-list-container', item => `【${item.getAttribute('name')}】\n目标：${item.getAttribute('target')}\n详情：${item.getAttribute('detail')}\n奖励：${item.getAttribute('reward')}`, 'reward');
            parseAndRenderList(`$13`, 'shop-list-container', item => `【${item.getAttribute('name')}】\n品质：${item.getAttribute('quality')}\n售价：${item.getAttribute('price')}\n作用：${item.getAttribute('effect')}`, 'price');

            const renderMap = () => {
                const container = document.getElementById('map-container');
                if (!container) return;

                // Set background image
                const mapBackgroundUrl = `$14`;
                if (mapBackgroundUrl && mapBackgroundUrl.trim() !== 'null') {
                    container.style.backgroundImage = `url('${mapBackgroundUrl}')`;
                }

                const points = parseXmlString(`$15`);
                for (const point of points) {
                    const mapPoint = document.createElement('div');
                    mapPoint.className = 'map-point';
                    mapPoint.style.left = point.getAttribute('x');
                    mapPoint.style.top = point.getAttribute('y');

                    const pointColor = point.getAttribute('color') || '#ff9500'; // Default color
                    mapPoint.style.backgroundColor = pointColor;
                    mapPoint.style.boxShadow = `0 0 6px ${pointColor}`;

                    mapPoint.onclick = () => alert(`【${point.getAttribute('name')}】\n详情：${point.getAttribute('detail')}`);
                    container.appendChild(mapPoint);
                }
            };

            const renderChoices = () => {
                const container = document.getElementById('choice-container');
                if (!container) return;
                const triggerQuickReply = (text) => {
                    if (typeof triggerSlash === 'function' && text.trim() !== '（保持沉默）') {
                        triggerSlash(`/send ${text.replace(/"/g, '')}|/trigger`);
                    } else { console.log(`Would trigger: /send ${text}`); }
                };
                const choices = parseXmlString(`$16`);
                for (const choice of choices) {
                    const button = document.createElement('div');
                    button.className = 'list-item';
                    button.textContent = choice.textContent;
                    button.addEventListener('click', () => triggerQuickReply(choice.textContent));
                    container.appendChild(button);
                }
            };

            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        if (entry.target.id === 'map-page') renderMap();
                        if (entry.target.id === 'choice-page') renderChoices();
                        observer.unobserve(entry.target);
                    }
                });
            }, { threshold: 0.1 });

            const mapPage = document.getElementById('map-page');
            const choicePage = document.getElementById('choice-page');
            if(mapPage) observer.observe(mapPage);
            if(choicePage) observer.observe(choicePage);
        });
    </script>
